css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:140px}
*,*::before,*::after{box-sizing:inherit}
[hidden]{display:none!important}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.1;letter-spacing:-.025em}
p{margin:0}a{color:inherit;text-decoration:none}ol,ul{margin:0;padding:0;list-style:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;position:relative;z-index:1}
section{padding:96px 0;position:relative}
.dk{background:var(--k);color:#fff}.lt{background:var(--w);color:var(--ink)}.gr{background:var(--g);color:var(--ink)}
.dk p{color:var(--dmute)}.lt p,.gr p{color:var(--mute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}.btn.xl{padding:18px 32px;font-size:17px}
.b-l{background:var(--l);color:var(--k)}.b-d{background:var(--k);color:#fff}
.eb{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;margin-bottom:22px}
.eb::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.dk .eb{color:var(--l)}.lt .eb,.gr .eb{color:var(--ink)}.lt .eb::before,.gr .eb::before{background:var(--k)}
.h2{font-size:clamp(30px,4.4vw,56px);letter-spacing:-.035em;line-height:1.05}
.fine{font-size:14px}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;font-size:14.5px;color:#d0d0d4}nav ul a:hover,nav ul a.on{color:var(--l)}nav .btn{padding:10px 18px;font-size:14px}
/* motion */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
.mk{display:block;overflow:hidden;padding-bottom:.1em;margin-bottom:-.1em}.mk>span{display:block}
.js .mk>span{transform:translateY(110%);transition:transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.js .in .mk>span,.js .mk.in>span{transform:none}
/* hero */
.hero{padding:96px 0 88px;background:radial-gradient(circle at 88% 0,#C7FF3F12,transparent 45%),var(--k)}
.hero h1{font-size:clamp(36px,6.4vw,88px);line-height:1;letter-spacing:-.045em;max-width:900px}
.hero h1 .m{color:var(--l)}
.hero .sub{margin-top:26px;font-size:clamp(17px,2vw,20px);max-width:560px;color:#d6d6da}
/* visuals */
.vis{height:170px;border-radius:16px;background:var(--k);position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;padding:18px}
.vis.lm{background:var(--l)}
.ln{height:6px;border-radius:3px;background:#2a2a2e}.ln.w{background:#e9e9ea;height:9px;width:60%}
.pill{display:inline-block;padding:4px 10px;border-radius:99px;background:var(--l);color:var(--k);font:600 9px Inter}
.fr{width:80%;background:var(--k2);border:1px solid var(--dline);border-radius:10px;padding:10px;display:grid;gap:8px}
.fr .hb{height:40px;border-radius:6px;background:linear-gradient(135deg,#25252a,#141416);padding:8px;display:grid;gap:5px;align-content:center}
.fr .c3{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.fr .c3 i{height:22px;border-radius:5px;background:#1c1c20;border:1px solid var(--dline)}
.fr .dt{display:flex;gap:4px}.fr .dt b{width:6px;height:6px;border-radius:50%;background:#333}
.phs{width:78px;height:150px;border:2px solid #34343a;border-radius:16px;background:#17171a;padding:14px 8px;display:grid;gap:7px;align-content:start;margin-top:30px}
.nds{display:flex;align-items:center;gap:8px;width:92%}.nd2{flex:1;height:36px;border:1px solid var(--dline);border-radius:9px;background:#17171a}.nd2.a{border-color:var(--l)}.cn{width:14px;height:2px;background:var(--l);flex:none}
.mks{width:80%;display:grid;gap:12px}.sbar{height:26px;border-radius:99px;border:1px solid var(--dline);background:#17171a;display:flex;align-items:center;padding-left:14px}.sbar i{width:40%;height:5px;border-radius:3px;background:#34343a}
.bars{display:flex;align-items:flex-end;gap:7px;height:64px}.bars i{flex:1;background:#2a2a2e;border-radius:3px 3px 0 0}.bars i:last-child{background:var(--l)}
.gbar{display:flex;align-items:flex-end;gap:12px;width:86%;height:230px}.gbar i{flex:1;border:2px solid var(--k);border-bottom:0;border-radius:8px 8px 0 0;background:transparent}.gbar i:last-child{background:var(--k)}
.cl{width:82%;display:grid;gap:10px}.cl div{display:flex;align-items:center;gap:10px}.cl b{width:16px;height:16px;border-radius:5px;border:1.5px solid #4a4a50;flex:none;display:grid;place-items:center;font:700 10px Inter;color:var(--k)}.cl b.y{background:var(--l);border-color:var(--l)}.cl .ln{flex:1}
/* featured */
.ft{display:grid;grid-template-columns:1.25fr 1fr;gap:56px;align-items:center}
.ft .vis{height:440px;border-radius:28px;padding:34px}
.big{display:grid;grid-template-columns:1fr 24px 1fr 24px 1fr;gap:10px;align-items:center;width:100%}
.big .col{display:grid;gap:10px}.big .n{border:1px solid var(--dline);border-radius:12px;background:#17171a;padding:12px 14px;font-size:13px;color:#e0e0e4}.big .n.a{border-color:var(--l);padding:26px 14px;text-align:center;font:600 15px Sora;color:var(--l);box-shadow:0 0 0 5px #C7FF3F1a}
.big .ar{height:2px;background:var(--l);opacity:.6}
.cat{display:inline-block;font:600 11.5px Inter;letter-spacing:.08em;padding:5px 12px;border-radius:99px;background:var(--k);color:var(--l);margin-bottom:18px}
.ft h2{font-size:clamp(28px,3.6vw,48px);letter-spacing:-.035em;margin-bottom:16px}.ft .tx>p{font-size:17px;margin-bottom:22px}
.meta{display:flex;gap:14px;flex-wrap:wrap;font-size:13.5px;color:var(--mute)}.meta span+span::before{content:"·";margin-right:14px}
.rd{display:inline-flex;gap:8px;font:600 15px Inter;border-bottom:2px solid var(--l);padding-bottom:2px}
/* category nav */
.cbar{position:sticky;top:68px;z-index:25;background:#f3f4f6f2;border-bottom:1px solid var(--line);border-top:1px solid var(--line)}
.cbar .wrap{display:flex;gap:10px;padding-top:14px;padding-bottom:14px;overflow-x:auto;scrollbar-width:none}
.cbar button{flex:none;font:600 14px Inter;padding:10px 20px;border-radius:99px;border:1.5px solid var(--line);background:#fff;color:var(--ink);cursor:pointer;transition:background .15s}
.cbar button:hover{border-color:var(--k)}.cbar button[aria-pressed="true"]{background:var(--k);border-color:var(--k);color:var(--l)}
/* grid */
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;grid-auto-flow:dense;padding:48px 0 0}
.ac{background:#fff;border:1px solid var(--line);border-radius:24px;padding:14px;display:flex;flex-direction:column;transition:transform .25s,border-color .25s}
.ac:hover{transform:translateY(-5px);border-color:var(--k)}
.ac .bd{padding:20px 10px 10px;display:flex;flex-direction:column;flex:1}
.ac .cat{align-self:flex-start;margin-bottom:14px;background:var(--g);color:var(--ink)}
.ac h3{font-size:20px;margin-bottom:10px;line-height:1.2}.ac .bd>p{font-size:15px;margin-bottom:18px}
.ac .ft2{margin-top:auto;display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:13px;color:var(--mute);border-top:1px solid var(--line);padding-top:14px}
.ac .ft2 a{font:600 14px Inter;color:var(--ink);border-bottom:2px solid var(--l)}
.ac.wide{grid-column:span 2;flex-direction:row;gap:10px}.ac.wide .vis{flex:1 1 44%;height:auto;min-height:260px}.ac.wide .bd{flex:1 1 50%;padding:18px 14px 8px}.ac.wide h3{font-size:24px}
.ac.tall{grid-row:span 2}.ac.tall .vis{height:330px}.ac.tall h3{font-size:22px}
.ac.txt{background:var(--k);border-color:var(--k);color:#fff;padding:26px}.ac.txt .bd{padding:0}.ac.txt h3{font-size:26px}.ac.txt .bd>p{color:var(--dmute)}.ac.txt .cat{background:var(--l);color:var(--k)}.ac.txt .ft2{border-color:var(--dline);color:var(--dmute)}.ac.txt .ft2 a{color:#fff}
.note{margin-top:28px}
/* topics */
.tp{display:grid;grid-template-columns:1fr 1fr;gap:0 56px;margin-top:44px}
.tp a{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:22px 0;border-top:1px solid var(--line);font:600 clamp(20px,2.4vw,30px) Sora;letter-spacing:-.03em;transition:padding-left .3s}
.tp a::after{content:"↗";font:600 20px Inter;color:var(--mute);transition:color .2s}
.tp a:hover{padding-left:14px}.tp a:hover::after{color:var(--k)}
.tp li:nth-last-child(-n+2) a{border-bottom:1px solid var(--line)}
/* newsletter */
.nl .wrap{display:grid;grid-template-columns:1.1fr 1fr;gap:56px;align-items:center}
.nl h2{font-size:clamp(38px,6.4vw,84px);letter-spacing:-.045em;line-height:1}.nl h2 .m{color:var(--l)}
.nl p{font-size:17px;margin-bottom:22px;max-width:440px}
.nl form{display:flex;gap:10px}
.nl input{flex:1;min-width:0;padding:16px 22px;border-radius:99px;border:1.5px solid #3a3a40;background:var(--k2);color:#fff;font:400 16px Inter}
.nl input::placeholder{color:#6f6f75}.nl input:focus{outline:2px solid var(--l);outline-offset:2px;border-color:var(--l)}
.nl .msg{margin-top:14px;font-size:14px;color:var(--l);min-height:22px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:112px 0}.cta h2{font-size:clamp(36px,6.2vw,80px);letter-spacing:-.045em;line-height:1;max-width:900px;margin-bottom:38px}
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.fg{display:grid;grid-template-columns:1.6fr repeat(4,1fr);gap:36px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}footer h4{font-size:14px;margin-bottom:14px}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.bgw{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.ft,.nl .wrap{grid-template-columns:1fr;gap:36px}.ft .vis{height:340px}
.grid{grid-template-columns:1fr 1fr}.ac.wide{grid-column:span 2}.ac.tall{grid-row:auto}.ac.tall .vis{height:250px}
.fg{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:860px){nav ul{display:none}.tp{grid-template-columns:1fr}.tp li:nth-last-child(-n+2) a{border-bottom:0}.tp li:last-child a{border-bottom:1px solid var(--line)}}
/* mobile */
@media(max-width:600px){
section{padding:68px 0}.wrap{padding:0 20px}.hero{padding:64px 0 60px}
.ft .vis{height:auto;padding:18px}.big{grid-template-columns:1fr;gap:8px}.big .ar{width:2px;height:20px;margin:0 auto}
.grid{grid-template-columns:1fr;gap:16px}.ac.wide{grid-column:auto;flex-direction:column}.ac.wide .vis{min-height:0;height:170px;flex:none}.ac.wide .bd{padding:20px 10px 10px}
.nl form{flex-direction:column}.nl .btn{justify-content:center}.btn.xl{width:100%;justify-content:center}
.fg{grid-template-columns:1fr 1fr}.fg>div:first-child{grid-column:span 2}.cta{padding:76px 0}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv,.js .mk>span{opacity:1;transform:none}}

js:
(function(){
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var els=document.querySelectorAll('.rv');
  if(!('IntersectionObserver' in window)||reduce){els.forEach(function(e){e.classList.add('in')});}
  else{var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{threshold:.12,rootMargin:'0px 0px -6% 0px'});els.forEach(function(e){io.observe(e)});}
  /* category filter */
  var tabs=document.querySelectorAll('.cbar button'),cards=document.querySelectorAll('#grid .ac');
  function apply(f){
    cards.forEach(function(c){c.hidden=!(f==='all'||c.getAttribute('data-cat')===f);});
    tabs.forEach(function(t){t.setAttribute('aria-pressed',t.getAttribute('data-f')===f?'true':'false');});
  }
  tabs.forEach(function(t){t.addEventListener('click',function(){apply(t.getAttribute('data-f'));});});
  /* newsletter: demo only, connect to an email provider */
  var f=document.getElementById('sub'),m=document.getElementById('msg'),em=document.getElementById('em');
  f.addEventListener('submit',function(e){
    e.preventDefault();
    var ok=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em.value);
    m.textContent=ok?'Thanks. This form is a design demo and isn’t connected to an email service yet.':'Please enter a valid email address.';
    if(ok)em.value='';
  });
})();
